package com.vstream.Vidiserver;

/** The "Ask Alma" chat bubble served at /alma.js (made from a file by the update script - do not edit by hand). */
final class AlmaWidget {

    private AlmaWidget() {
    }

    static final String JS = ""
            + "// Alma - Memoryq's assistant. Add to a page with: <script src=\"/alma.js\" defer></script>\n"
            + "(function () {\n"
            + "  if (window.__alma) return;\n"
            + "  window.__alma = true;\n"
            + "  var KEY = 'alma_chat';\n"
            + "  var msgs = [];\n"
            + "  try { msgs = JSON.parse(sessionStorage.getItem(KEY) || '[]') || []; } catch (e) { msgs = []; }\n"
            + "  function save() { try { sessionStorage.setItem(KEY, JSON.stringify(msgs.slice(-30))); } catch (e) { } }\n"
            + "\n"
            + "  var host = document.createElement('div');\n"
            + "  host.style.cssText = 'position:fixed;right:18px;bottom:18px;z-index:2147483000';\n"
            + "  document.body.appendChild(host);\n"
            + "  var root = host.attachShadow ? host.attachShadow({ mode: 'open' }) : host;\n"
            + "  root.innerHTML =\n"
            + "    '<style>' +\n"
            + "    '*{box-sizing:border-box;font-family:system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}' +\n"
            + "    '.fab{width:56px;height:56px;border-radius:50%;border:0;cursor:pointer;background:linear-gradient(135deg,#3d7bff,#7b4dff);color:#fff;font-weight:800;font-size:22px;box-shadow:0 6px 22px rgba(0,0,0,.35);display:flex;align-items:center;justify-content:center}' +\n"
            + "    '.fab:hover{transform:scale(1.05)}' +\n"
            + "    '.tip{position:absolute;right:66px;bottom:12px;background:#111a24;color:#fff;font-size:13px;padding:6px 10px;border-radius:14px;white-space:nowrap;box-shadow:0 4px 14px rgba(0,0,0,.3)}' +\n"
            + "    '.panel{position:absolute;right:0;bottom:68px;width:350px;max-width:calc(100vw - 24px);height:480px;max-height:calc(100vh - 100px);background:#fff;color:#1b1f23;border-radius:16px;box-shadow:0 12px 40px rgba(0,0,0,.35);display:none;flex-direction:column;overflow:hidden}' +\n"
            + "    '.panel.open{display:flex}' +\n"
            + "    '.head{background:#111a24;color:#fff;padding:12px 14px;display:flex;align-items:center;gap:10px}' +\n"
            + "    '.av{width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,#3d7bff,#7b4dff);display:flex;align-items:center;justify-content:center;font-weight:800}' +\n"
            + "    '.head b{display:block;font-size:15px}.head small{color:#9fb0c2;font-size:12px}' +\n"
            + "    '.x{margin-left:auto;background:none;border:0;color:#cfd8e2;font-size:22px;cursor:pointer;line-height:1}' +\n"
            + "    '.body{flex:1;overflow-y:auto;padding:12px;background:#f3f5f8;display:flex;flex-direction:column;gap:8px}' +\n"
            + "    '.m{max-width:85%;padding:9px 12px;border-radius:14px;font-size:14px;line-height:1.4;white-space:pre-wrap;word-wrap:break-word}' +\n"
            + "    '.m.a{background:#fff;border:1px solid #e3e8ee;align-self:flex-start;border-bottom-left-radius:4px}' +\n"
            + "    '.m.u{background:#3d7bff;color:#fff;align-self:flex-end;border-bottom-right-radius:4px}' +\n"
            + "    '.m a{color:#2f6fed}.m.u a{color:#fff}' +\n"
            + "    '.chips{display:flex;flex-wrap:wrap;gap:6px}' +\n"
            + "    '.chip{border:1px solid #c9d6ea;background:#fff;color:#2f6fed;border-radius:14px;padding:5px 10px;font-size:13px;cursor:pointer}' +\n"
            + "    '.typing{color:#6b7a88;font-size:13px;padding:2px 4px}' +\n"
            + "    '.foot{display:flex;gap:6px;padding:10px;border-top:1px solid #e3e8ee;background:#fff}' +\n"
            + "    '.foot input{flex:1;border:1px solid #d5dde6;border-radius:18px;padding:9px 12px;font-size:14px;outline:none;color:#1b1f23;background:#fff}' +\n"
            + "    '.foot input:focus{border-color:#3d7bff}' +\n"
            + "    '.send{border:0;background:#3d7bff;color:#fff;border-radius:18px;padding:0 14px;font-weight:700;cursor:pointer}' +\n"
            + "    '.note{font-size:11px;color:#8a98a8;text-align:center;padding:0 10px 8px;background:#fff}' +\n"
            + "    '</style>' +\n"
            + "    '<div class=\"panel\" id=\"panel\" role=\"dialog\" aria-label=\"Chat with Alma\">' +\n"
            + "    '<div class=\"head\"><div class=\"av\">A</div><div><b>Alma</b><small>Memoryq assistant</small></div><button class=\"x\" id=\"x\" aria-label=\"Close\">&times;</button></div>' +\n"
            + "    '<div class=\"body\" id=\"body\"></div>' +\n"
            + "    '<div class=\"foot\"><input id=\"q\" maxlength=\"500\" placeholder=\"Ask me anything about Memoryq\" aria-label=\"Your question\"><button class=\"send\" id=\"send\">Send</button></div>' +\n"
            + "    '<div class=\"note\">Alma can make mistakes. Never share your password.</div>' +\n"
            + "    '</div>' +\n"
            + "    '<span class=\"tip\" id=\"tip\">Ask Alma</span>' +\n"
            + "    '<button class=\"fab\" id=\"fab\" aria-label=\"Ask Alma, the Memoryq assistant\">A</button>';\n"
            + "\n"
            + "  var $ = function (id) { return root.getElementById ? root.getElementById(id) : root.querySelector('#' + id); };\n"
            + "  var panel = $('panel'), body = $('body'), q = $('q');\n"
            + "  var busy = false;\n"
            + "  setTimeout(function () { var t = $('tip'); if (t) t.style.display = 'none'; }, 6000);\n"
            + "\n"
            + "  function esc(s) { return String(s).replace(/[&<>\"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; }); }\n"
            + "  function linkify(s) {\n"
            + "    return esc(s).replace(/(https?:\\/\\/[^\\s<)]+[^\\s<).,!?;:])|([a-z0-9._%+-]+@memoryq\\.com)/gi, function (m, url, mail) {\n"
            + "      if (mail) return '<a href=\"mailto:' + mail + '\">' + mail + '</a>';\n"
            + "      var same = /^https?:\\/\\/(www\\.)?memoryq\\.com/i.test(url);\n"
            + "      return '<a href=\"' + url + '\"' + (same ? '' : ' target=\"_blank\" rel=\"noopener\"') + '>' + url + '</a>';\n"
            + "    });\n"
            + "  }\n"
            + "  function add(who, text) {\n"
            + "    var d = document.createElement('div');\n"
            + "    d.className = 'm ' + who;\n"
            + "    d.innerHTML = linkify(text);\n"
            + "    body.appendChild(d);\n"
            + "    body.scrollTop = body.scrollHeight;\n"
            + "  }\n"
            + "  function chips() {\n"
            + "    var c = document.createElement('div');\n"
            + "    c.className = 'chips';\n"
            + "    ['How do I sign up?', 'Download the app', 'Find a radio station', 'Upload a video', 'Go live from my phone'].forEach(function (t) {\n"
            + "      var b = document.createElement('button');\n"
            + "      b.className = 'chip'; b.textContent = t;\n"
            + "      b.onclick = function () { ask(t); };\n"
            + "      c.appendChild(b);\n"
            + "    });\n"
            + "    body.appendChild(c);\n"
            + "  }\n"
            + "  function draw() {\n"
            + "    body.innerHTML = '';\n"
            + "    add('a', \"Hi, I'm Alma! I can help you find your way around Memoryq.\");\n"
            + "    if (!msgs.length) chips();\n"
            + "    msgs.forEach(function (m) { add(m.w, m.t); });\n"
            + "  }\n"
            + "  function ask(text) {\n"
            + "    text = (text || '').trim();\n"
            + "    if (!text || busy) return;\n"
            + "    busy = true;\n"
            + "    var ctx = msgs.slice(-6).map(function (m) { return (m.w === 'u' ? 'Visitor: ' : 'Alma: ') + m.t; }).join('\\n');\n"
            + "    msgs.push({ w: 'u', t: text }); save(); draw();\n"
            + "    var t = document.createElement('div'); t.className = 'typing'; t.textContent = 'Alma is typing...'; body.appendChild(t);\n"
            + "    body.scrollTop = body.scrollHeight;\n"
            + "    fetch('/api/alma/ask', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: 'q=' + encodeURIComponent(text) + '&ctx=' + encodeURIComponent(ctx) })\n"
            + "      .then(function (r) { return r.json(); })\n"
            + "      .then(function (j) { msgs.push({ w: 'a', t: j.answer || j.error || 'Sorry, something went wrong.' }); })\n"
            + "      .catch(function () { msgs.push({ w: 'a', t: 'I cannot reach the server right now - please try again in a moment.' }); })\n"
            + "      .then(function () { busy = false; save(); draw(); q.focus(); });\n"
            + "  }\n"
            + "  function open(on) {\n"
            + "    panel.classList.toggle('open', on);\n"
            + "    var t = $('tip'); if (t) t.style.display = 'none';\n"
            + "    if (on) { draw(); setTimeout(function () { q.focus(); }, 50); }\n"
            + "  }\n"
            + "  $('fab').onclick = function () { open(!panel.classList.contains('open')); };\n"
            + "  $('x').onclick = function () { open(false); };\n"
            + "  $('send').onclick = function () { var v = q.value; q.value = ''; ask(v); };\n"
            + "  q.addEventListener('keydown', function (e) { if (e.key === 'Enter') { var v = q.value; q.value = ''; ask(v); } e.stopPropagation(); });\n"
            + "  q.addEventListener('keyup', function (e) { e.stopPropagation(); });\n"
            + "  document.addEventListener('fullscreenchange', function () { host.style.display = document.fullscreenElement ? 'none' : ''; });\n"
            + "  window.Alma = { open: function () { open(true); }, ask: function (t) { open(true); ask(t); } };\n"
            + "})();\n"
            + "\n";
}